pub enum CT_Vector_Choice {
    /// `vt:variant` — Variant (§22.4.2.32).
    Variant(Box<CT_Variant>),
    /// `vt:i1` — 1-Byte Signed Integer (§22.4.2.12).
    I1(i8),
    /// `vt:i2` — 2-Byte Signed Integer (§22.4.2.13).
    I2(i16),
    /// `vt:i4` — 4-Byte Signed Integer (§22.4.2.14).
    I4(i32),
    /// `vt:i8` — 8-Byte Signed Integer (§22.4.2.15).
    I8(i64),
    /// `vt:ui1` — 1-Byte Unsigned Integer (§22.4.2.27).
    Ui1(u8),
    /// `vt:ui2` — 2-Byte Unsigned Integer (§22.4.2.28).
    Ui2(u16),
    /// `vt:ui4` — 4-Byte Unsigned Integer (§22.4.2.29).
    Ui4(u32),
    /// `vt:ui8` — 8-Byte Unsigned Integer (§22.4.2.30).
    Ui8(u64),
    /// `vt:r4` — 4-Byte Real Number (§22.4.2.23).
    R4(f32),
    /// `vt:r8` — 8-Byte Real Number (§22.4.2.24).
    R8(f64),
    /// `vt:lpstr` — LPSTR (§22.4.2.17).
    Lpstr(String),
    /// `vt:lpwstr` — LPWSTR (§22.4.2.18).
    Lpwstr(String),
    /// `vt:bstr` — Basic String (§22.4.2.4).
    Bstr(String),
    /// `vt:date` — Date and Time (§22.4.2.7).
    Date(String),
    /// `vt:filetime` — File Time (§22.4.2.11).
    Filetime(String),
    /// `vt:bool` — Boolean (§22.4.2.3).
    Bool(bool),
    /// `vt:cy` — Currency (§22.4.2.6).
    Cy(ST_Cy),
    /// `vt:error` — Error Status Code (§22.4.2.10).
    Error(ST_Error),
    /// `vt:clsid` — Class ID (§22.4.2.5).
    Clsid(crate::shared_types::ST_Guid),
    /// An element not described by the schema, kept as raw XML.
    Other(RawElement),
}

impl CT_Vector_Choice {
    /// Reads the variant for the element opened by `tag`.
    pub fn read_choice(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        Ok(match (tag.ns(), tag.local()) {
            (Ns::VT, "variant") => Self::Variant(Box::new(XmlRead::read_xml(r, tag)?)),
            (Ns::VT, "i1") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::I1(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "i2") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::I2(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "i4") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::I4(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "i8") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::I8(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "ui1") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Ui1(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "ui2") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Ui2(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "ui4") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Ui4(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "ui8") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Ui8(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "r4") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::R4(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "r8") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::R8(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "lpstr") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Lpstr(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "lpwstr") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Lpwstr(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "bstr") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Bstr(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "date") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Date(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "filetime") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Filetime(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "bool") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Bool(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "cy") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Cy(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "error") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Error(v),
                Err(raw) => Self::Other(raw),
            },
            (Ns::VT, "clsid") => match rt::read_simple(r, tag)? {
                Ok(v) => Self::Clsid(v),
                Err(raw) => Self::Other(raw),
            },
            _ => Self::Other(RawElement::read(r, tag)?),
        })
    }

    /// Writes the variant as an element.
    pub fn write_choice(&self, w: &mut XmlWriter) {
        match self {
            Self::Variant(v) => v.write_xml(w, Ns::VT, "variant"),
            Self::I1(v) => rt::write_simple(w, Ns::VT, "i1", v),
            Self::I2(v) => rt::write_simple(w, Ns::VT, "i2", v),
            Self::I4(v) => rt::write_simple(w, Ns::VT, "i4", v),
            Self::I8(v) => rt::write_simple(w, Ns::VT, "i8", v),
            Self::Ui1(v) => rt::write_simple(w, Ns::VT, "ui1", v),
            Self::Ui2(v) => rt::write_simple(w, Ns::VT, "ui2", v),
            Self::Ui4(v) => rt::write_simple(w, Ns::VT, "ui4", v),
            Self::Ui8(v) => rt::write_simple(w, Ns::VT, "ui8", v),
            Self::R4(v) => rt::write_simple(w, Ns::VT, "r4", v),
            Self::R8(v) => rt::write_simple(w, Ns::VT, "r8", v),
            Self::Lpstr(v) => rt::write_simple(w, Ns::VT, "lpstr", v),
            Self::Lpwstr(v) => rt::write_simple(w, Ns::VT, "lpwstr", v),
            Self::Bstr(v) => rt::write_simple(w, Ns::VT, "bstr", v),
            Self::Date(v) => rt::write_simple(w, Ns::VT, "date", v),
            Self::Filetime(v) => rt::write_simple(w, Ns::VT, "filetime", v),
            Self::Bool(v) => rt::write_simple(w, Ns::VT, "bool", v),
            Self::Cy(v) => rt::write_simple(w, Ns::VT, "cy", v),
            Self::Error(v) => rt::write_simple(w, Ns::VT, "error", v),
            Self::Clsid(v) => rt::write_simple(w, Ns::VT, "clsid", v),
            Self::Other(v) => v.write(w),
        }
    }

    /// Namespace and local name of the element this variant represents.
    pub fn element_name(&self) -> (Ns, &str) {
        match self {
            Self::Variant(_) => (Ns::VT, "variant"),
            Self::I1(_) => (Ns::VT, "i1"),
            Self::I2(_) => (Ns::VT, "i2"),
            Self::I4(_) => (Ns::VT, "i4"),
            Self::I8(_) => (Ns::VT, "i8"),
            Self::Ui1(_) => (Ns::VT, "ui1"),
            Self::Ui2(_) => (Ns::VT, "ui2"),
            Self::Ui4(_) => (Ns::VT, "ui4"),
            Self::Ui8(_) => (Ns::VT, "ui8"),
            Self::R4(_) => (Ns::VT, "r4"),
            Self::R8(_) => (Ns::VT, "r8"),
            Self::Lpstr(_) => (Ns::VT, "lpstr"),
            Self::Lpwstr(_) => (Ns::VT, "lpwstr"),
            Self::Bstr(_) => (Ns::VT, "bstr"),
            Self::Date(_) => (Ns::VT, "date"),
            Self::Filetime(_) => (Ns::VT, "filetime"),
            Self::Bool(_) => (Ns::VT, "bool"),
            Self::Cy(_) => (Ns::VT, "cy"),
            Self::Error(_) => (Ns::VT, "error"),
            Self::Clsid(_) => (Ns::VT, "clsid"),
            Self::Other(v) => (v.name.ns, &v.name.local),
        }
    }
}

/// Global elements of this schema. Each can be the root of a document part.
pub mod elements {
    use super::*;

    /// `vt:variant` — Variant (§22.4.2.32).
    pub const VARIANT: ElementDef<CT_Variant> = ElementDef::new(Ns::VT, "variant", &[Ns::VT]);

    /// `vt:vector` — Vector (§22.4.2.33).
    pub const VECTOR: ElementDef<CT_Vector> = ElementDef::new(Ns::VT, "vector", &[Ns::VT]);

    /// `vt:array` — Array (§22.4.2.1).
    pub const ARRAY: ElementDef<CT_Array> = ElementDef::new(Ns::VT, "array", &[Ns::VT]);

    /// `vt:empty` — Empty (§22.4.2.9).
    pub const EMPTY: ElementDef<CT_Empty> = ElementDef::new(Ns::VT, "empty", &[Ns::VT]);

    /// `vt:null` — Null (§22.4.2.19).
    pub const NULL: ElementDef<CT_Null> = ElementDef::new(Ns::VT, "null", &[Ns::VT]);

    /// `vt:vstream` — Binary Versioned Stream (§22.4.2.34).
    pub const VSTREAM: ElementDef<CT_Vstream> = ElementDef::new(Ns::VT, "vstream", &[Ns::VT]);
}
